import java.util.*;

class Solution {
    private List<String> result = new ArrayList<>();

    public List<String> generateParenthesis(int n) {
        char[] buf = new char[2 * n];
        gen(buf, 0, n);
        return result;
    }

    private void gen(char[] buf, int index, int n) {
        if (index == buf.length) {
            String s = new String(buf);
            if (isValid(s)) result.add(s);
            return;
        }
        buf[index] = '(';
        gen(buf, index + 1, n);
        buf[index] = ')';
        gen(buf, index + 1, n);
    }

    private boolean isValid(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') balance++;
            else balance--;
            if (balance < 0) return false;   // 右括号超前，立刻非法
        }
        return balance == 0;
    }
}

import java.util.*;

class Solution {
    private List<String> result = new ArrayList<>();
    private char[] buf;

    public List<String> generateParenthesis(int n) {
        buf = new char[2 * n];
        backtrack(0, 0, n);
        return result;
    }

    private void backtrack(int open, int close, int n) {
        if (open + close == 2 * n) {
            result.add(new String(buf));
            return;
        }
        if (open < n) {                    // 左括号不能超 n 个
            buf[open + close] = '(';
            backtrack(open + 1, close, n);
        }
        if (close < open) {                // 右括号不能多于左括号
            buf[open + close] = ')';
            backtrack(open, close + 1, n);
        }
    }
}

import java.util.*;

class Solution {
    private List<String>[] memo;

    public List<String> generateParenthesis(int n) {
        memo = new List[n + 1];
        List<String> base = new ArrayList<>();
        base.add("");                    // 基底：0 对括号只有空串
        memo[0] = base;
        return solve(n);
    }

    private List<String> solve(int k) {
        if (memo[k] != null) return memo[k];

        List<String> res = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            for (String a : solve(i)) {
                for (String b : solve(k - 1 - i)) {
                    res.add("(" + a + ")" + b);
                }
            }
        }
        memo[k] = res;
        return res;
    }
}
